"use client"

import { useEffect, useState } from "react"
import { motion, AnimatePresence } from "framer-motion"
import { Award, Bell, BookOpen, Calendar, CheckCircle2, Edit, Eye, GraduationCap, Home, Mail, Menu, PanelLeft, Plus, Save, Trash2, UserPlus, X, FileText, ClipboardList } from 'lucide-react'

import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Progress } from "@/components/ui/progress"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Textarea } from "@/components/ui/textarea"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Checkbox } from "@/components/ui/checkbox"
import { cn } from "@/lib/utils"

// Simulando as APIs - substitua pelos imports reais
const dashboardApi = {
  getDashboard: async () => ({ metricasProgresso: {}, materiasResumidas: [], professores: [] })
}

const studentApi = {
  getProfile: async () => ({ id: "1", name: "Estudante", email: "aluno@email.com", phone: "" }),
  getStats: async () => ({ totalSubjects: 0, totalTeachers: 0, totalNotes: 0, overallScore: 0, attendanceRate: 0, assignmentCompletionRate: 0 }),
  updateProfile: async (data: any) => {}
}

const teachersApi = {
  create: async (data: any) => {},
  update: async (id: number, data: any) => {},
  delete: async (id: number) => {}
}

const subjectsApi = {
  create: async (data: any) => {},
  update: async (id: number, data: any) => {},
  delete: async (id: number) => {},
  registerAttendance: async (id: number) => {},
  addTrabalho: async (materiaId: number, data: any) => {},
  updateTrabalho: async (materiaId: number, trabalhoId: number, data: any) => {},
  deleteTrabalho: async (materiaId: number, trabalhoId: number) => {}
}

const notesApi = {
  getAll: async () => [],
  create: async (data: any) => {},
  update: async (id: number, data: any) => {},
  delete: async (id: number) => {}
}

const authApi = {
  logout: () => {}
}

const sidebarItems = [
  { title: "Painel", icon: <Home />, value: "painel" },
  { title: "Aulas", icon: <BookOpen />, value: "aulas" },
  { title: "Professores", icon: <UserPlus />, value: "professores" },
  { title: "Anotações", icon: <FileText />, value: "anotacoes" },
  { title: "Perfil", icon: <GraduationCap />, value: "perfil" },
]

const COLORS = [
  { label: "Azul", value: "bg-blue-500" },
  { label: "Verde", value: "bg-green-500" },
  { label: "Roxo", value: "bg-purple-500" },
  { label: "Rosa", value: "bg-pink-500" },
  { label: "Amarelo", value: "bg-yellow-500" },
  { label: "Vermelho", value: "bg-red-500" },
]

export default function DashboardPage() {
  const [activeTab, setActiveTab] = useState("painel")
  const [sidebarOpen, setSidebarOpen] = useState(true)
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)

  const [teachers, setTeachers] = useState<any[]>([])
  const [subjects, setSubjects] = useState<any[]>([])
  const [notes, setNotes] = useState<any[]>([])
  const [student, setStudent] = useState<any>(null)
  const [loading, setLoading] = useState(false)

  // Modals
  const [teacherModal, setTeacherModal] = useState(false)
  const [subjectModal, setSubjectModal] = useState(false)
  const [noteModal, setNoteModal] = useState(false)
  const [trabalhoModal, setTrabalhoModal] = useState(false)
  const [editingTeacher, setEditingTeacher] = useState<any>(null)
  const [editingSubject, setEditingSubject] = useState<any>(null)
  const [editingNote, setEditingNote] = useState<any>(null)
  const [currentSubjectForTrabalho, setCurrentSubjectForTrabalho] = useState<any>(null)
  const [editingTrabalho, setEditingTrabalho] = useState<any>(null)

  // Form states
  const [teacherForm, setTeacherForm] = useState({ nome: "", email: "", disciplina: "" })
  const [subjectForm, setSubjectForm] = useState({ nome: "", cor: "bg-blue-500", professorId: "", notaProva: "" })
  const [noteForm, setNoteForm] = useState({ titulo: "", conteudo: "", materiaId: "" })
  const [trabalhoForm, setTrabalhoForm] = useState({ titulo: "", descricao: "", dataEntrega: "", concluido: false })
  const [profileForm, setProfileForm] = useState({ nome: "", email: "", telefone: "" })

  useEffect(() => {
    loadDashboardData()
  }, [])

  const loadDashboardData = async () => {
    setLoading(true)
    try {
      const studentData = await studentApi.getProfile()
      setStudent(studentData)
      setProfileForm({ nome: studentData.name, email: studentData.email, telefone: studentData.phone || "" })
      
      // Mock data
      setTeachers([
        { id: "1", name: "Prof. João Silva", subject: "Matemática", email: "joao@email.com" },
        { id: "2", name: "Profa. Maria Santos", subject: "Física", email: "maria@email.com" }
      ])
      
      setSubjects([
        { 
          id: "1", 
          name: "Matemática Avançada", 
          teacher: "Prof. João Silva", 
          teacherId: "1",
          color: "bg-blue-500",
          totalClasses: 40,
          attendedClasses: 35,
          assignments: 5,
          completedAssignments: 4,
          testGrade: 8.5,
          trabalhos: [
            { id: 1, titulo: "Trabalho 1", descricao: "Exercícios de cálculo", dataEntrega: "2025-12-01", concluido: true },
            { id: 2, titulo: "Trabalho 2", descricao: "Prova de teoremas", dataEntrega: "2025-12-15", concluido: false }
          ]
        }
      ])
    } finally {
      setLoading(false)
    }
  }

  const calculateScore = () => {
    const totalClasses = subjects.reduce((acc, s) => acc + s.totalClasses, 0)
    const attendedClasses = subjects.reduce((acc, s) => acc + s.attendedClasses, 0)
    const attendanceRate = totalClasses > 0 ? (attendedClasses / totalClasses) * 100 : 0

    const totalAssignments = subjects.reduce((acc, s) => acc + s.assignments, 0)
    const completedAssignments = subjects.reduce((acc, s) => acc + s.completedAssignments, 0)
    const assignmentRate = totalAssignments > 0 ? (completedAssignments / totalAssignments) * 100 : 0

    return Math.round((attendanceRate + assignmentRate) / 2)
  }

  // Teacher CRUD
  const openTeacherModal = (teacher?: any) => {
    if (teacher) {
      setEditingTeacher(teacher)
      setTeacherForm({ nome: teacher.name, email: teacher.email, disciplina: teacher.subject })
    } else {
      setEditingTeacher(null)
      setTeacherForm({ nome: "", email: "", disciplina: "" })
    }
    setTeacherModal(true)
  }

  const saveTeacher = async () => {
    try {
      if (editingTeacher) {
        await teachersApi.update(parseInt(editingTeacher.id), teacherForm)
      } else {
        await teachersApi.create(teacherForm)
      }
      await loadDashboardData()
      setTeacherModal(false)
    } catch (error) {
      alert("Erro ao salvar professor")
    }
  }

  // Subject CRUD
  const openSubjectModal = (subject?: any) => {
    if (subject) {
      setEditingSubject(subject)
      setSubjectForm({
        nome: subject.name,
        cor: subject.color,
        professorId: subject.teacherId || "",
        notaProva: subject.testGrade?.toString() || ""
      })
    } else {
      setEditingSubject(null)
      setSubjectForm({ nome: "", cor: "bg-blue-500", professorId: "", notaProva: "" })
    }
    setSubjectModal(true)
  }

  const saveSubject = async () => {
    try {
      if (!subjectForm.nome || !subjectForm.professorId) {
        alert("Nome da matéria e professor são obrigatórios")
        return
      }

      const data = {
        nome: subjectForm.nome,
        cor: subjectForm.cor,
        professorId: parseInt(subjectForm.professorId),
        notaProva: subjectForm.notaProva ? parseFloat(subjectForm.notaProva) : undefined
      }

      if (editingSubject) {
        await subjectsApi.update(parseInt(editingSubject.id), data)
      } else {
        await subjectsApi.create(data)
      }
      await loadDashboardData()
      setSubjectModal(false)
    } catch (error) {
      alert("Erro ao salvar matéria: " + (error instanceof Error ? error.message : ""))
    }
  }

  // Trabalho CRUD
  const openTrabalhoModal = (subject: any, trabalho?: any) => {
    setCurrentSubjectForTrabalho(subject)
    if (trabalho) {
      setEditingTrabalho(trabalho)
      setTrabalhoForm({
        titulo: trabalho.titulo,
        descricao: trabalho.descricao || "",
        dataEntrega: trabalho.dataEntrega,
        concluido: trabalho.concluido
      })
    } else {
      setEditingTrabalho(null)
      setTrabalhoForm({ titulo: "", descricao: "", dataEntrega: "", concluido: false })
    }
    setTrabalhoModal(true)
  }

  const saveTrabalho = async () => {
    try {
      if (!trabalhoForm.titulo || !trabalhoForm.dataEntrega) {
        alert("Título e data de entrega são obrigatórios")
        return
      }

      const materiaId = parseInt(currentSubjectForTrabalho.id)

      if (editingTrabalho) {
        await subjectsApi.updateTrabalho(materiaId, editingTrabalho.id, trabalhoForm)
      } else {
        await subjectsApi.addTrabalho(materiaId, trabalhoForm)
      }
      
      await loadDashboardData()
      setTrabalhoModal(false)
    } catch (error) {
      alert("Erro ao salvar trabalho: " + (error instanceof Error ? error.message : ""))
    }
  }

  const deleteTrabalho = async (subjectId: string, trabalhoId: number) => {
    if (!confirm("Deseja realmente excluir este trabalho?")) return

    try {
      await subjectsApi.deleteTrabalho(parseInt(subjectId), trabalhoId)
      await loadDashboardData()
    } catch (error) {
      alert("Erro ao deletar trabalho")
    }
  }

  const saveProfile = async () => {
    try {
      await studentApi.updateProfile({
        nome: profileForm.nome,
        telefone: profileForm.telefone
      })
      alert("Perfil atualizado com sucesso!")
    } catch (error) {
      alert("Erro ao atualizar perfil")
    }
  }

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center">
        <div className="text-center space-y-4">
          <GraduationCap className="h-16 w-16 mx-auto animate-pulse text-primary" />
          <p className="text-lg text-muted-foreground">Carregando dashboard...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="relative min-h-screen overflow-hidden bg-background">
      <motion.div
        className="absolute inset-0 -z-10 opacity-20"
        animate={{
          background: [
            "radial-gradient(circle at 50% 50%, rgba(59, 130, 246, 0.5) 0%, rgba(147, 51, 234, 0.5) 50%, rgba(0, 0, 0, 0) 100%)",
            "radial-gradient(circle at 30% 70%, rgba(16, 185, 129, 0.5) 0%, rgba(59, 130, 246, 0.5) 50%, rgba(0, 0, 0, 0) 100%)",
            "radial-gradient(circle at 70% 30%, rgba(147, 51, 234, 0.5) 0%, rgba(16, 185, 129, 0.5) 50%, rgba(0, 0, 0, 0) 100%)",
          ],
        }}
        transition={{ duration: 30, repeat: Infinity, ease: "linear" }}
      />

      <div className={cn("fixed inset-y-0 left-0 z-30 hidden w-64 transform border-r bg-background transition-transform duration-300 ease-in-out md:block", sidebarOpen ? "translate-x-0" : "-translate-x-full")}>
        <div className="flex h-full flex-col">
          <div className="p-4">
            <div className="flex items-center gap-3">
              <div className="flex aspect-square size-10 items-center justify-center rounded-2xl bg-gradient-to-br from-blue-600 to-purple-600 text-white">
                <GraduationCap className="size-5" />
              </div>
              <div>
                <h2 className="font-semibold">Zoombi</h2>
                <p className="text-xs text-muted-foreground">Organize seus estudos</p>
              </div>
            </div>
          </div>

          <ScrollArea className="flex-1 px-3 py-2">
            <div className="space-y-1">
              {sidebarItems.map((item) => (
                <button
                  key={item.value}
                  onClick={() => setActiveTab(item.value)}
                  className={cn("flex w-full items-center gap-3 rounded-2xl px-3 py-2 text-sm font-medium", activeTab === item.value ? "bg-primary/10 text-primary" : "hover:bg-muted")}
                >
                  {item.icon}
                  <span>{item.title}</span>
                </button>
              ))}
            </div>
          </ScrollArea>

          <div className="border-t p-3">
            <button className="flex w-full items-center gap-3 rounded-2xl px-3 py-2 text-sm font-medium hover:bg-muted">
              <Avatar className="h-6 w-6">
                <AvatarFallback>{student?.name?.charAt(0) || "E"}</AvatarFallback>
              </Avatar>
              <span>{student?.name || "Estudante"}</span>
            </button>
          </div>
        </div>
      </div>

      <div className={cn("min-h-screen transition-all duration-300 ease-in-out", sidebarOpen ? "md:pl-64" : "md:pl-0")}>
        <header className="sticky top-0 z-10 flex h-16 items-center gap-3 border-b bg-background/95 px-4 backdrop-blur">
          <Button variant="ghost" size="icon" className="hidden md:flex" onClick={() => setSidebarOpen(!sidebarOpen)}>
            <PanelLeft className="h-5 w-5" />
          </Button>
          <div className="flex flex-1 items-center justify-between">
            <h1 className="text-xl font-semibold">Olá, {student?.name || "Estudante"}!</h1>
            <Avatar className="h-9 w-9 border-2 border-primary">
              <AvatarFallback>{student?.name?.charAt(0) || "E"}</AvatarFallback>
            </Avatar>
          </div>
        </header>

        <main className="flex-1 p-4 md:p-6">
          <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
            <TabsContent value="aulas" className="space-y-8 mt-0">
              <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="overflow-hidden rounded-3xl bg-gradient-to-r from-emerald-600 via-teal-600 to-cyan-600 p-8 text-white">
                <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
                  <div className="space-y-2">
                    <h2 className="text-3xl font-bold">Minhas Aulas</h2>
                    <p className="max-w-[600px] text-white/80">Acompanhe suas matérias, notas e trabalhos</p>
                  </div>
                  <Button className="w-fit rounded-2xl bg-white text-emerald-700 hover:bg-white/90" onClick={() => openSubjectModal()}>
                    <Plus className="mr-2 h-4 w-4" />
                    Nova Matéria
                  </Button>
                </div>
              </motion.div>

              <section className="space-y-4">
                <h2 className="text-2xl font-semibold">Todas as Matérias</h2>
                <div className="grid grid-cols-1 gap-4">
                  {subjects.map((subject) => (
                    <Card key={subject.id} className="overflow-hidden rounded-3xl border-2">
                      <CardHeader>
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-3">
                            <div className={cn("h-12 w-12 rounded-2xl flex items-center justify-center text-white", subject.color)}>
                              <BookOpen className="h-6 w-6" />
                            </div>
                            <div>
                              <CardTitle className="text-xl">{subject.name}</CardTitle>
                              <CardDescription>{subject.teacher}</CardDescription>
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <Badge className="rounded-xl text-lg px-3 py-1">Nota: {subject.testGrade}</Badge>
                            <Button variant="outline" size="icon" className="rounded-2xl" onClick={() => openSubjectModal(subject)}>
                              <Edit className="h-4 w-4" />
                            </Button>
                          </div>
                        </div>
                      </CardHeader>
                      <CardContent className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                          <div className="space-y-2">
                            <div className="flex items-center justify-between text-sm">
                              <span className="font-medium">Frequência</span>
                              <span>{Math.round((subject.attendedClasses / Math.max(subject.totalClasses, 1)) * 100)}%</span>
                            </div>
                            <Progress value={(subject.attendedClasses / Math.max(subject.totalClasses, 1)) * 100} className="h-2 rounded-xl" />
                          </div>
                          <div className="space-y-2">
                            <div className="flex items-center justify-between text-sm">
                              <span className="font-medium">Trabalhos</span>
                              <span>{subject.completedAssignments}/{subject.assignments}</span>
                            </div>
                            <Progress value={(subject.completedAssignments / Math.max(subject.assignments, 1)) * 100} className="h-2 rounded-xl" />
                          </div>
                          <div className="space-y-2">
                            <div className="flex items-center justify-between text-sm">
                              <span className="font-medium">Desempenho</span>
                              <span>{subject.testGrade}/10</span>
                            </div>
                            <Progress value={subject.testGrade * 10} className="h-2 rounded-xl" />
                          </div>
                        </div>

                        <div className="border-t pt-4">
                          <div className="flex items-center justify-between mb-3">
                            <h3 className="font-semibold flex items-center gap-2">
                              <ClipboardList className="h-4 w-4" />
                              Trabalhos
                            </h3>
                            <Button size="sm" variant="outline" className="rounded-xl" onClick={() => openTrabalhoModal(subject)}>
                              <Plus className="h-3 w-3 mr-1" />
                              Adicionar
                            </Button>
                          </div>
                          {subject.trabalhos && subject.trabalhos.length > 0 ? (
                            <div className="space-y-2">
                              {subject.trabalhos.map((trabalho: any) => (
                                <div key={trabalho.id} className="flex items-center justify-between p-3 rounded-xl border bg-muted/50">
                                  <div className="flex items-center gap-3">
                                    <Checkbox checked={trabalho.concluido} />
                                    <div>
                                      <p className="font-medium text-sm">{trabalho.titulo}</p>
                                      <p className="text-xs text-muted-foreground">Entrega: {new Date(trabalho.dataEntrega).toLocaleDateString('pt-BR')}</p>
                                    </div>
                                  </div>
                                  <div className="flex gap-1">
                                    <Button size="sm" variant="ghost" className="h-8 w-8 p-0" onClick={() => openTrabalhoModal(subject, trabalho)}>
                                      <Edit className="h-3 w-3" />
                                    </Button>
                                    <Button size="sm" variant="ghost" className="h-8 w-8 p-0 text-red-500" onClick={() => deleteTrabalho(subject.id, trabalho.id)}>
                                      <Trash2 className="h-3 w-3" />
                                    </Button>
                                  </div>
                                </div>
                              ))}
                            </div>
                          ) : (
                            <p className="text-sm text-muted-foreground text-center py-4">Nenhum trabalho cadastrado</p>
                          )}
                        </div>
                      </CardContent>
                    </Card>
                  ))}
                </div>
              </section>
            </TabsContent>

            <TabsContent value="perfil" className="space-y-8 mt-0">
              <Card className="rounded-3xl">
                <CardHeader>
                  <CardTitle>Informações Pessoais</CardTitle>
                  <CardDescription>Gerencie suas informações</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-2">
                    <Label>Nome Completo</Label>
                    <Input value={profileForm.nome} onChange={(e) => setProfileForm({ ...profileForm, nome: e.target.value })} className="rounded-2xl" />
                  </div>
                  <div className="space-y-2">
                    <Label>Email</Label>
                    <Input value={profileForm.email} disabled className="rounded-2xl" />
                  </div>
                  <div className="space-y-2">
                    <Label>Telefone</Label>
                    <Input value={profileForm.telefone} onChange={(e) => setProfileForm({ ...profileForm, telefone: e.target.value })} className="rounded-2xl" />
                  </div>
                </CardContent>
                <CardFooter>
                  <Button className="w-full rounded-2xl" onClick={saveProfile}>
                    <Save className="mr-2 h-4 w-4" />
                    Salvar Alterações
                  </Button>
                </CardFooter>
              </Card>
            </TabsContent>
          </Tabs>
        </main>
      </div>

      {/* Modal Matéria */}
      <Dialog open={subjectModal} onOpenChange={setSubjectModal}>
        <DialogContent className="sm:max-w-[600px] rounded-3xl">
          <DialogHeader>
            <DialogTitle>{editingSubject ? "Editar Matéria" : "Adicionar Matéria"}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Nome da Matéria *</Label>
              <Input value={subjectForm.nome} onChange={(e) => setSubjectForm({ ...subjectForm, nome: e.target.value })} className="rounded-2xl" />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Professor *</Label>
                <Select value={subjectForm.professorId} onValueChange={(value) => setSubjectForm({ ...subjectForm, professorId: value })}>
                  <SelectTrigger className="rounded-2xl">
                    <SelectValue placeholder="Selecione" />
                  </SelectTrigger>
                  <SelectContent>
                    {teachers.map((t) => (
                      <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Nota da Prova (0-10)</Label>
                <Input type="number" step="0.1" min="0" max="10" value={subjectForm.notaProva} onChange={(e) => setSubjectForm({ ...subjectForm, notaProva: e.target.value })} className="rounded-2xl" placeholder="Ex: 8.5" />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Cor</Label>
              <Select value={subjectForm.cor} onValueChange={(value) => setSubjectForm({ ...subjectForm, cor: value })}>
                <SelectTrigger className="rounded-2xl">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {COLORS.map((c) => (
                    <SelectItem key={c.value} value={c.value}>
                      <div className="flex items-center gap-2">
                        <div className={cn("w-4 h-4 rounded-full", c.value)} />
                        {c.label}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1 rounded-2xl" onClick={() => setSubjectModal(false)}>Cancelar</Button>
            <Button className="flex-1 rounded-2xl" onClick={saveSubject}>
              <Save className="mr-2 h-4 w-4" />
              Salvar
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Modal Trabalho */}
      <Dialog open={trabalhoModal} onOpenChange={setTrabalhoModal}>
        <DialogContent className="sm:max-w-[500px] rounded-3xl">
          <DialogHeader>
            <DialogTitle>{editingTrabalho ? "Editar Trabalho" : "Adicionar Trabalho"}</DialogTitle>
            <DialogDescription>
              Matéria: {currentSubjectForTrabalho?.name}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Título *</Label>
              <Input value={trabalhoForm.titulo} onChange={(e) => setTrabalhoForm({ ...trabalhoForm, titulo: e.target.value })} className="rounded-2xl" placeholder="Ex: Trabalho Final" />
            </div>
            <div className="space-y-2">
              <Label>Descrição</Label>
              <Textarea value={trabalhoForm.descricao} onChange={(e) => setTrabalhoForm({ ...trabalhoForm, descricao: e.target.value })} className="rounded-2xl" placeholder="Detalhes do trabalho..." rows={3} />
            </div>
            <div className="space-y-2">
              <Label>Data de Entrega *</Label>
              <Input type="date" value={trabalhoForm.dataEntrega} onChange={(e) => setTrabalhoForm({ ...trabalhoForm, dataEntrega: e.target.value })} className="rounded-2xl" />
            </div>
            <div className="flex items-center space-x-2">
              <Checkbox id="concluido" checked={trabalhoForm.concluido} onCheckedChange={(checked) => setTrabalhoForm({ ...trabalhoForm, concluido: checked as boolean })} />
              <Label htmlFor="concluido" className="cursor-pointer">Trabalho concluído</Label>
            </div>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" className="flex-1 rounded-2xl" onClick={() => setTrabalhoModal(false)}>Cancelar</Button>
            <Button className="flex-1 rounded-2xl" onClick={saveTrabalho}>
              <Save className="mr-2 h-4 w-4" />
              Salvar
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}